#pragma once
#include "one_layer_frontier_probe.h"
// After the integrated Attention observer mismatch: bounded, independent lanes.
inline void copyReceipt(const std::vector<uint32_t>& r,const one::FV& input,const std::vector<uint32_t>& output,unsigned& last){unsigned n=input.size();if(r.size()!=3*n+8||r[0]!=0x48383100u||r[1]<=last||r[2]!=n||r[3]!=1||r[5]!=81||r[7]){std::puts("BOUNDARY_COPY_RECEIPT_FAIL");std::exit(3);}last=r[1];for(unsigned j=0;j<n;++j)if(r[8+j]!=word(input[j])||r[8+n+j]||r[8+2*n+j]||output[j]!=word(input[j])){std::puts("BOUNDARY_COPY_WORD_FAIL");std::exit(3);}}
inline unsigned bounded(const std::string& requested,const std::vector<one::Fixture>& fs){
 unsigned failures=0,selectorFailures=0;std::vector<one::FV> gradients(24),weights(24);std::vector<std::map<std::string,one::FV>> anchors(24);
 for(auto mode:{"segmentNative","segmentTap","segmentFused"}){std::string name=mode;bool tap=name!="segmentNative",fused=name=="segmentFused";OneGraph graph(name,tap,fused,false,false);
  for(auto& z:fs){auto ref=one::reference(z),fp=one::reference(z,true);auto o=graph.g.run(graph.inputs(z));auto actual=graph.audit(z,o);for(auto key:{"dc","dw","y","xhat","inverse","dx","dg","db","residual"})failures+=metric(name,z.index,key,ref.at(key),fp.at(key),actual.at(key),limit(key));
   if(name=="segmentNative"){anchors[z.index]=actual;gradients[z.index]=actual.at("dc");weights[z.index]=actual.at("dw");}else for(auto key:{"dc","dw","y","dx","residual"})if(actual.at(key)!=anchors[z.index].at(key)){std::puts("BOUND_SEGMENT_OBSERVER_FAIL");std::exit(3);}
   std::printf("onefixture,%s,%u,checkpoint=%u,gradient_hash=%016llx,dwo_hash=%016llx\n",name.c_str(),z.index,z.checkpoint,(unsigned long long)hashWords(gradients[z.index]),(unsigned long long)hashWords(weights[z.index]));
  }if(failures){std::puts("BOUND_SEGMENT_ACCURACY_STOP");return 4;}
  for(unsigned rep=0;rep<9;++rep){auto o=graph.g.run(graph.inputs(fs[0]));graph.audit(fs[0],o);std::printf("oneperf,%s,%u,wall_us=%.3f,dc_us=%u,dw_us=%u\n",name.c_str(),rep,graph.g.executeUs,o[graph.cr][4],o[graph.wr][4]);}
 }
 accumulation(fs,weights);
 if(requested=="oneBoundary"||requested=="oneFinal")for(unsigned head=0;head<2;++head){std::vector<std::vector<uint32_t>> anchor(24);for(auto mode:{"direct","native","tap","nativeOutput"}){std::string name=mode;DiagnosticGraph g("selector"+std::to_string(head)+name);auto x=g.tensor("gradient",QNN_TENSOR_TYPE_APP_WRITE,{1,1,32,64});unsigned mid=x,copy=0,outputCopy=0,last=0;auto si=g.constant("selector",{1,1,64,32},[&](){one::FV s(2048);for(unsigned c=0;c<32;++c)s[(head*32+c)*32+c]=1;return s;}());
   if(name=="native"||name=="tap"){mid=g.tensor("native",name=="tap"?QNN_TENSOR_TYPE_APP_READ:QNN_TENSOR_TYPE_NATIVE,{1,1,32,64});copy=g.tensor("receipt",QNN_TENSOR_TYPE_APP_READ,{1,1,1,6152},QNN_DATATYPE_INT_32);g.node("copy","Copy","HexaFp32",{x},{mid,copy});}
   auto y=g.tensor("selected",name=="nativeOutput"?QNN_TENSOR_TYPE_NATIVE:QNN_TENSOR_TYPE_APP_READ,{1,1,32,32});op::mm(g,"head_selector",mid,si,y);auto read=y;if(name=="nativeOutput"){read=g.tensor("readback",QNN_TENSOR_TYPE_APP_READ,{1,1,32,32});outputCopy=g.tensor("output_receipt",QNN_TENSOR_TYPE_APP_READ,{1,1,1,3080},QNN_DATATYPE_INT_32);g.node("consumer","Copy","HexaFp32",{y},{read,outputCopy});}g.finalize();
   for(unsigned i=0;i<24;++i){auto o=g.run({{x,gradients[i]}});if(copy){auto midWords=std::vector<uint32_t>();for(float a:gradients[i])midWords.push_back(word(a));copyReceipt(o[copy],gradients[i],midWords,last);if(name=="tap"&&o[mid]!=midWords){std::puts("SELECTOR_INPUT_OBSERVER_FAIL");std::exit(3);}}
    auto result=decode(o[read]);if(outputCopy)copyReceipt(o[outputCopy],result,o[read],last);if(name=="direct")anchor[i]=o[read];else if(anchor[i]!=o[read]){std::puts("SELECTOR_OUTPUT_OBSERVER_FAIL");std::exit(3);}auto ref=one::split(one::d(gradients[i]),head),half=ref;for(auto& v:half)v=mmfixture::ln::halfLattice(v);unsigned lost=0;for(unsigned j=0;j<1024;++j)lost+=word(float(ref[j]))!=o[read][j];auto key="h"+std::to_string(head)+"_selected";selectorFailures+=metric("selector_"+name,i,key,ref,ref,result,.002);selectorFailures+=lost!=0;std::printf("selectorfrontier,%s,%u,%u,words_lost=%u,half_output_model_abs=%.12g,input_receipt_preserved=1,observer_equal=1\n",name.c_str(),head,i,lost,mmfixture::ln::errors(half,result).absolute);
   }
  }}
 unsigned prototypeBad=0,producerBad=0;if(requested=="oneFinal"){if(!selectorFailures){std::puts("HEAD_SPLIT_PROTOTYPE_REQUIRES_SELECTOR_BLOCKER");return 4;}prototypeBad=splitPrototype(fs,gradients);producerBad=producers(fs);}
 struct rusage usage{};getrusage(RUSAGE_SELF,&usage);std::printf("peak_rss_kib,%ld\n",usage.ru_maxrss);std::printf("summary,%s,segment_failures=0,selector_failures=%u,prototype_failures=%u,producer_local_custom_failures=%u,accumulation_verified=1,cpu_fallback=0,input_mutation=0,finite=1,poison_remaining=0,canary_failures=0,training_updates=0\n",requested.c_str(),selectorFailures,prototypeBad,producerBad);return prototypeBad||producerBad?4:0;
}
